"use strict";

/**
 * Offline regression test for the bundled `am` CLI's page template:
 * rendered pages must not carry the "Generated by … · ★ Star on GitHub"
 * colophon line. The `<meta name="generator">` tag is untouched.
 *
 *   node --test tests/
 *
 * It runs the bundled CLI with `AM_HOME` pointing at a temporary directory, so
 * nothing lands in the user's own pages folder.
 */

const assert = require("node:assert/strict");
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { after, before, test } = require("node:test");

const pages = require("../lib/pages");

const AM_SCRIPT = path.join(__dirname, "..", "skills", "answer-me-with-html", "scripts", "am.mjs");

let home;

function runAm(args, input) {
  return spawnSync(process.execPath, [AM_SCRIPT, ...args], {
    input,
    encoding: "utf8",
    env: { ...process.env, AM_HOME: home },
    timeout: 60000,
  });
}

before(() => {
  home = fs.mkdtempSync(path.join(os.tmpdir(), "am-colophon-test-"));
});

after(() => {
  fs.rmSync(home, { recursive: true, force: true });
});

test("a rendered page has no colophon line", () => {
  const draft = ["---", "title: Colophon smoke page", "---", "## A Why", "```flow", "A -> B: one step", "```", ""].join("\n");
  const rendered = runAm(["render", "--no-open", "-"], draft);
  assert.equal(rendered.status, 0, rendered.stderr || rendered.stdout);

  const listed = pages.listPages(home);
  assert.equal(listed.total, 1);
  const html = fs.readFileSync(path.join(listed.roots[0].pagesDir, listed.pages[0].name), "utf8");
  assert.doesNotMatch(html, /<p class="am-colophon">/);
  assert.doesNotMatch(html, /Generated by/);
  assert.doesNotMatch(html, /Star on GitHub/);
  // The generator meta tag is not part of the colophon line and stays.
  assert.match(html, /<meta name="generator" content="Answer me with HTML /);
});
